// Verb data generated by scripts/generate-verbs.mjs (src/data/verbs/*.json).
// The index (list) loads with the page; conjugations load when a verb is opened.

export type VerbTense = { key: string; name: string }
export type VerbMood = { name: string; tenses: VerbTense[] }

export type VerbEntry = {
  id: string
  infinitive: string
  /** Translations keyed by language (en, es) */
  translations: Record<string, string>
  /** Lesson where the verb first appears; 0 for essential verbs */
  lesson: number
  slug: string | null
  essential: boolean
  pronominal: boolean
  /** French auxiliary for compound tenses */
  aux: 'être' | 'avoir' | null
  participles: { present: string | null; past: string | null }
}

export type VerbIndex = {
  language: string
  moods: VerbMood[]
  persons: string[]
  imperativePersons: string[]
  participleLabels: { present: string; past: string }
  note: string | null
  verbs: VerbEntry[]
}

/** Tense key → one form per person (null where the verb has no such form) */
export type VerbForms = Record<string, (string | null)[]>

/** An example sentence for one tense; match is the verb form in it (highlighted) */
export type VerbExample = { text: string; translations: Record<string, string>; match: string }
/** Tense key → example */
export type VerbExamples = Record<string, VerbExample>

export const VERB_LANGUAGES = ['fr', 'en'] as const

export async function loadVerbIndex(lang: string): Promise<VerbIndex | null> {
  switch (lang) {
    case 'fr': return (await import('@/data/verbs/fr-index.json')).default as VerbIndex
    case 'en': return (await import('@/data/verbs/en-index.json')).default as VerbIndex
    default: return null
  }
}

export async function loadVerbForms(lang: string): Promise<Record<string, VerbForms> | null> {
  switch (lang) {
    case 'fr': return (await import('@/data/verbs/fr-forms.json')).default as Record<string, VerbForms>
    case 'en': return (await import('@/data/verbs/en-forms.json')).default as Record<string, VerbForms>
    default: return null
  }
}

export function verbTranslation(verb: VerbEntry, translationLang: string): string {
  return verb.translations[translationLang] ?? verb.translations.en ?? verb.translations.es ?? ''
}

/** Text to read aloud: "il/elle est" → "il est", "he/she is" → "he is" */
export function speakableForm(form: string): string {
  return form.replace(/\b(il|ils|he)\/(elle|elles|she)\b/g, '$1')
}

export async function loadVerbExamples(lang: string): Promise<Record<string, VerbExamples> | null> {
  switch (lang) {
    case 'fr': return (await import('@/data/verbs/fr-examples.json')).default as Record<string, VerbExamples>
    case 'en': return (await import('@/data/verbs/en-examples.json')).default as Record<string, VerbExamples>
    default: return null
  }
}
